from pathlib import Path
from typing import Any, Dict, List, Optional
from fastapi import HTTPException, status

from app.config import DISCLAIMER_TEXT, SAVED_MODELS_DIR, WORKSPACE_DIR
from app.tasks.base import BaseMriTask, TaskInfo, TaskSetupGuide, TaskStatus

class MultipleSclerosisTask(BaseMriTask):
    """
    Modular task for Multiple Sclerosis (MS) White Matter Lesion Analysis.
    Currently in setup state: requires FLAIR/T2 multi-spectral dataset
    and trained model checkpoint.
    """

    task_id = "multiple-sclerosis"
    name = "Multiple Sclerosis MRI Analysis"
    short_title = "Multiple Sclerosis"
    category = "Demyelinating Diseases"
    tagline = "Multi-sequence T2-FLAIR hyperintensity detection & lesion burden quantification"
    description = (
        "Focuses on detecting, categorizing, and quantifying inflammatory demyelinating lesions "
        "in the central nervous system across periventricular, juxtacortical, and infratentorial regions. "
        "Requires multi-contrast MRI sequences to differentiate active from chronic lesions."
    )
    supported_scan_types = ["MRI"]
    required_sequences = ["T2-FLAIR (Fluid-Attenuated Inversion Recovery)", "T2-weighted", "T1-weighted post-Gadolinium"]
    supported_orientations = ["Axial", "Sagittal"]
    supported_formats = [".jpg", ".jpeg", ".png"]
    limitations = [
        "Dataset & Model Setup Required: This task is currently unconfigured. No inference allowed.",
        "Multiple Sclerosis diagnosis requires demonstrating dissemination in space and time (revised McDonald Criteria).",
        "White matter hyperintensities on T2/FLAIR are non-specific and occur in microvascular ischemic disease, migraine, and aging.",
        "Intensity normalization and bias-field correction (N4ITK) are mandatory for reliable automated lesion evaluation.",
    ]
    disclaimer = DISCLAIMER_TEXT

    def __init__(self):
        self.model_path = SAVED_MODELS_DIR / "axonova_ms_best.keras"
        self.dataset_dir = WORKSPACE_DIR / "dataset" / "multiple_sclerosis"

    def is_ready(self) -> bool:
        return self.model_path.exists() and self.dataset_dir.exists()

    def get_status(self) -> TaskStatus:
        return "ready" if self.is_ready() else "setup_required"

    def get_class_labels(self) -> List[str]:
        return []

    def get_setup_guide(self) -> TaskSetupGuide:
        return TaskSetupGuide(
            recommended_datasets=[
                "ISBI MS Lesion Segmentation Challenge Dataset - smart-stats-tools.org/lesion-challenge",
                "MICCAI MSSEG (Multiple Sclerosis Segmentation Challenge) Benchmark",
                "OpenMS / Zenodo Multiple Sclerosis Multi-Center Cohort",
            ],
            required_sequences=["T2-FLAIR", "T2-weighted Fast Spin Echo", "T1-weighted contrast-enhanced"],
            split_policy=(
                "PATIENT-LEVEL MULTI-VISIT SPLIT: Multiple Sclerosis patients undergo frequent follow-up MRIs. "
                "All historical scans and slices for a given patient identifier must be grouped into the same "
                "split partition to prevent temporal and anatomical data leakage."
            ),
            target_classes=[
                "Active Demyelinating Lesion",
                "Chronic Inactive Lesion",
                "Normal Appearing White Matter (NAWM)",
            ],
            expected_model_path=str(self.model_path),
            expected_dataset_dir=str(self.dataset_dir),
            data_leakage_risks=[
                "Longitudinal visit leakage across multi-year disease monitoring.",
                "Periventricular slice correlations from the same imaging session.",
                "Non-standardized FLAIR inversion times creating sequence bias.",
            ],
            setup_steps=[
                "1. Download approved multi-sequence MS research repository.",
                "2. Apply N4 bias field correction and register T1/T2 to FLAIR space.",
                "3. Structure slices at dataset/multiple_sclerosis/{train,val,test}/ with patient-level splits.",
                "4. Train task-specific pipeline: python -m model.train_ms.",
                "5. Save checkpoint to backend/saved_models/axonova_ms_best.keras.",
            ],
        )

    def get_task_info(self) -> TaskInfo:
        return TaskInfo(
            task_id=self.task_id,
            name=self.name,
            short_title=self.short_title,
            category=self.category,
            status=self.get_status(),
            tagline=self.tagline,
            description=self.description,
            supported_scan_types=self.supported_scan_types,
            required_sequences=self.required_sequences,
            supported_orientations=self.supported_orientations,
            supported_formats=self.supported_formats,
            class_labels=self.get_class_labels(),
            model_loaded=self.is_ready(),
            model_name=None,
            model_version=None,
            input_shape=None,
            trainable_parameters=None,
            evaluation_available=False,
            overall_accuracy=None,
            limitations=self.limitations,
            disclaimer=self.disclaimer,
            setup_guide=self.get_setup_guide(),
        )

    def get_model_info(self) -> Dict[str, Any]:
        return {
            "loaded": False,
            "task_id": self.task_id,
            "model_name": None,
            "training_status": "Dataset/model setup required",
            "supported_classes": [],
            "supported_scan_type": "MRI",
            "evaluation_available": False,
            "disclaimer": self.disclaimer,
            "setup_guide": self.get_setup_guide().model_dump(),
        }

    def get_evaluation(self) -> Dict[str, Any]:
        return {
            "evaluated": False,
            "task_id": self.task_id,
            "reason": "Model weights and evaluation results not configured yet.",
            "disclaimer": self.disclaimer,
        }

    def get_dataset_info(self) -> Dict[str, Any]:
        return {
            "available": False,
            "task_id": self.task_id,
            "dataset_name": "Multiple Sclerosis MRI Dataset",
            "source": "ISBI / MICCAI MSSEG (Pending Setup)",
            "total_images": 0,
            "class_distribution": {},
            "split_counts": {},
            "disclaimer": self.disclaimer,
            "setup_guide": self.get_setup_guide().model_dump(),
        }

    def predict(
        self,
        file_bytes: bytes,
        scan_type: str,
        orientation: str,
        filename: str = "uploaded_scan.jpg",
    ) -> Dict[str, Any]:
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail=(
                "Task 'Multiple Sclerosis MRI Analysis' is not enabled. "
                "Multi-sequence dataset and trained model checkpoint are required. "
                "Simulated or placeholder predictions are strictly prohibited."
            ),
        )
